content.text:
{
  "primary_meaning": "spiritual perception, insight, or understanding (the capacity to receive light/truth or remain in darkness)",
  "primary_basis": [
    "Matthew 6:22-23 (eye as lamp of the body)",
    "Ephesians 1:18 (eyes of the heart enlightened)",
    "Mark 8:18 / Isaiah 6:9-10 (having eyes yet not seeing)",
    "Psalm 119:18 (open my eyes that I may see)"
  ],
  "alternatives": [
    {
      "meaning": "divine omniscience, watchfulness, or providential care (especially 'the eyes of the Lord')",
      "basis": [
        "Proverbs 15:3",
        "2 Chronicles 16:9",
        "Psalm 33:18 / 34:15",
        "Revelation 5:6 (seven eyes of the Lamb)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "envy, stinginess, or malice (the 'evil eye')",
      "basis": [
        "Matthew 6:23 (unhealthy/evil eye)",
        "Mark 7:22",
        "Proverbs 23:6 / 28:22"
      ],
      "prominence": "common"
    },
    {
      "meaning": "lust or covetous desire",
      "basis": [
        "1 John 2:16 (lust of the eyes)",
        "Matthew 5:28-29",
        "2 Peter 2:14"
      ],
      "prominence": "common"
    },
    {
      "meaning": "retributive justice (lex talionis)",
      "basis": [
        "Exodus 21:24",
        "Leviticus 24:20",
        "Matthew 5:38"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "high",
  "notes": "Biblical usage is strongly context-dependent; no single fixed symbol dominates every occurrence. Spiritual perception is the most frequently taught general association in Christian interpretation and preaching, while divine watchfulness and the evil-eye idiom are also standard. Meanings shift with whether the eye is human, divine, healthy, or evil."
}
